This FIFO uses all 17 slots and rejects overflow without modifying its contents. The invariant is that `head_` identifies the next item and `size_` counts stored items: zero means empty, 17 means full, and insertion occurs at `(head_ + size_) % 17`. Compile and run with assertions enabled: `g++ -std=c++17 -Wall -Wextra -pedantic fifo.cpp -o fifo`, then run the executable.

```cpp
#include <array>
#include <cassert>
#include <cstddef>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (size_ == capacity) {
            return false;
        }
        data_[(head_ + size_) % capacity] = value;
        ++size_;
        return true;
    }

    bool pop(int& value) {
        if (size_ == 0) {
            return false;
        }
        value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --size_;
        return true;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == capacity; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    BoundedFIFO fifo;
    int value = -1;
    bool ok = fifo.pop(value);
    assert(!ok && value == -1 && fifo.empty());

    // All 17 slots are usable.
    for (int i = 0; i < 17; ++i) {
        ok = fifo.push(i);
        assert(ok);
        assert(fifo.size() == static_cast<std::size_t>(i + 1));
    }
    assert(fifo.full());

    // Overflow leaves the size and every queued value unchanged.
    ok = fifo.push(999);
    assert(!ok && fifo.size() == 17 && fifo.full());
    for (int expected = 0; expected < 17; ++expected) {
        ok = fifo.pop(value);
        assert(ok && value == expected);
    }
    assert(fifo.empty());
    ok = fifo.pop(value);
    assert(!ok);

    // Retain four items, then insert across the array boundary.
    for (int i = 0; i < 12; ++i) {
        ok = fifo.push(i);
        assert(ok);
    }
    for (int expected = 0; expected < 8; ++expected) {
        ok = fifo.pop(value);
        assert(ok && value == expected);
    }
    for (int i = 12; i < 25; ++i) {
        ok = fifo.push(i);
        assert(ok);
    }
    assert(fifo.full());
    ok = fifo.push(999);
    assert(!ok && fifo.size() == 17);

    for (int expected = 8; expected < 25; ++expected) {
        ok = fifo.pop(value);
        assert(ok && value == expected);
    }
    assert(fifo.empty());
    ok = fifo.pop(value);
    assert(!ok);

    // The queue remains reusable after the wrapped drain.
    ok = fifo.push(42);
    assert(ok);
    ok = fifo.pop(value);
    assert(ok && value == 42 && fifo.empty());
    return 0;
}
```

The lower median is 4: the sorted values are [1,2,4,4,7,9]. The function copies the input before applying `std::nth_element`, so the caller’s array remains unchanged, and rejects empty input with `std::invalid_argument`.

For nonempty size n, select zero-based index `(n - 1) / 2`: if n = 2m + 1, this is m, the middle element; if n = 2m, this is m - 1, the lower of the two middle elements. `std::nth_element` places at that index the value that would occupy it after sorting, including when duplicates occur.

Save as `median.cpp`, compile with `g++ -std=c++17 -Wall -Wextra -pedantic median.cpp -o median`, and run with assertions enabled (do not define `NDEBUG`).

```cpp
#include <algorithm>
#include <cassert>
#include <cstddef>
#include <stdexcept>
#include <vector>

int lower_median(const std::vector<int>& values) {
    if (values.empty()) {
        throw std::invalid_argument("lower_median requires nonempty input");
    }

    std::vector<int> copy = values;
    const std::size_t index = (copy.size() - 1) / 2;
    auto selected = copy.begin() +
        static_cast<std::vector<int>::difference_type>(index);
    std::nth_element(copy.begin(), selected, copy.end());
    return *selected;
}

int main() {
    const auto check = [](const std::vector<int>& input, int expected) {
        const std::vector<int> original = input;
        const int result = lower_median(input);
        assert(result == expected);
        assert(input == original);
    };

    check({9, 1, 4, 4, 7, 2}, 4);  // Requested array and duplicates.
    check({5, 5, 5, 5}, 5);        // All values equal.
    check({9, 1, 7, 3, 5}, 5);     // Odd size.
    check({8, 2, 6, 4}, 4);        // Even size: lower middle, not 6.
    check({42}, 42);                // Singleton.

    const std::vector<int> empty;
    bool rejected = false;
    try {
        (void)lower_median(empty);
    } catch (const std::invalid_argument&) {
        rejected = true;
    }
    assert(rejected);
    assert(empty.empty());
    return 0;
}
```

No: keeping `desired` fixed can lose an increment. Suppose the counter is 0: thread A sets `expected=0, desired=1`; thread B increments it to 1; A’s CAS fails and updates `expected` to 1. A retries with `expected=1, desired=1`, succeeds in storing 1, and returns—two increments have produced only 1.

Recompute `desired` on every attempt, including after spurious failures; a failed CAS performs no write and updates `expected` with the observed value. Relaxed ordering suffices for this counter alone, and this implementation requires that incrementing never overflow `int`. Compile with `g++ -std=c++17 -O2 -Wall -Wextra -pedantic -pthread counter.cpp -o counter` and run with assertions enabled.

```cpp
#include <atomic>
#include <cassert>
#include <iostream>
#include <thread>
#include <vector>

void increment(std::atomic<int>& counter) {
    int expected = counter.load(std::memory_order_relaxed);
    for (;;) {
        const int desired = expected + 1;
        if (counter.compare_exchange_weak(
                expected, desired,
                std::memory_order_relaxed,
                std::memory_order_relaxed)) {
            return;
        }
        // Failure, including spurious failure: expected now contains
        // the observed value. Recompute desired on the next attempt.
    }
}

int main() {
    constexpr int thread_count = 8;
    constexpr int increments_per_thread = 100000;
    constexpr int expected_count =
        thread_count * increments_per_thread;

    std::atomic<int> counter{0};
    std::atomic<bool> start{false};
    std::vector<std::thread> threads;
    threads.reserve(thread_count);

    for (int i = 0; i < thread_count; ++i) {
        threads.emplace_back([&] {
            while (!start.load(std::memory_order_acquire)) {
                std::this_thread::yield();
            }
            for (int j = 0; j < increments_per_thread; ++j) {
                increment(counter);
            }
        });
    }

    start.store(true, std::memory_order_release);
    for (auto& thread : threads) {
        thread.join();
    }

    const int actual = counter.load(std::memory_order_relaxed);
    assert(actual == expected_count);
    std::cout << "Final count: " << actual << '\n';
    return actual == expected_count ? 0 : 1;
}
